  static deal(){const ids=MiniGame.tray().map(item=>item.id);const a=ids.splice(Math.floor(Math.random()*ids.length),1)[0],b=ids.splice(Math.floor(Math.random()*ids.length),1)[0];return [a,b]}
  static open(service){const item=product[service],kind=MiniGame.kind(service);round={service,shop:item.shop,kind,total:BarSpeed.seconds(item),t:0,picked:[],asked:kind==='pick'?MiniGame.deal():[],odd:kind==='odd'?MiniGame.oddSet():null,match:kind==='match'?MiniGame.matchSet():null,outfit:kind==='outfit'?MiniGame.outfitDeal():null,pattern:'',color:''};mode='minigame';MiniGame.render();syncHud()}
